import{_ as a,o as e,c as i,a5 as t}from"./chunks/framework.BjM_ivYE.js";const b=JSON.parse('{"title":"Image Echo — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/image-echo.md","filePath":"ko/software/sdk/cpp/image-echo.md","lastUpdated":1785817728000}'),o={name:"ko/software/sdk/cpp/image-echo.md"};function n(p,s,c,l,d,h){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="image-echo-—-c-예제" tabindex="-1">Image Echo — C++ 예제 <a class="header-anchor" href="#image-echo-—-c-예제" aria-label="Permalink to &quot;Image Echo — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_image_echo.cpp</code></p><p>압축 카메라 토픽을 <strong>구독</strong>해 초당 수신율, 마지막 프레임 크기, 이미지 포맷을 출력하는 읽기 전용 진단 도구입니다. 카메라 스트림이 실제로 발행되고 있는지, SDK 호스트에서 도달 가능한지 확인할 때 사용합니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><p>프로그램 동작:</p><ol><li><code>argv[1]</code>에서 토픽 이름을(기본값 <code>rt/rbq/vision/sensor_4/rgb/compressed</code>), <code>argv[2]</code>에서 네트워크 인터페이스를(기본값 <code>lo</code>) 읽습니다.</li><li>해당 인터페이스로 DDS <code>ChannelFactory</code>를 초기화하고 <code>Subscriber&lt;CompressedImage_&gt;</code>를 생성합니다.</li><li>샘플을 수신할 때마다 카운터, 마지막 바이트 크기, 이미지 포맷을 갱신합니다.</li><li>1초마다 경과 시간, 총 샘플 수, 1초 수신율, 마지막 프레임 크기, 포맷을 출력합니다.</li><li><code>Ctrl+C</code>(SIGINT/SIGTERM) 시 총 샘플 수를 출력하고 정상 종료합니다.</li></ol><p>발행은 하지 않으므로 실제 로봇이나 시뮬레이터와 함께 실행해도 안전합니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>압축 이미지 토픽을 발행하는 측이 실행 중이어야 합니다 — 로봇 비전 스택 또는 비전 포함 MuJoCo 시뮬레이터(<code>bash scripts/sim.bash --vision</code>).</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리 위치: <code>bin/rbq_image_echo</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><p>두 인자 모두 선택입니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [topic] [interface]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>인자</th><th>의미</th><th>기본값</th></tr></thead><tbody><tr><td><code>topic</code></td><td>구독할 압축 이미지 토픽</td><td><code>rt/rbq/vision/sensor_4/rgb/compressed</code></td></tr><tr><td><code>interface</code></td><td>CycloneDDS 인터페이스</td><td><code>lo</code></td></tr></tbody></table><h3 id="mujoco-시뮬레이터에서" tabindex="-1">MuJoCo 시뮬레이터에서 <a class="header-anchor" href="#mujoco-시뮬레이터에서" aria-label="Permalink to &quot;MuJoCo 시뮬레이터에서&quot;">​</a></h3><p>시뮬레이터는 <code>lo</code> 로 발행하며, 이 예제의 기본값과 같으므로 인자가 필요 없습니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 한 터미널에서</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 다른 터미널에서</span></span></code></pre></div><p>카메라는 로봇·심 모두 <strong>숫자 id</strong>를 씁니다. <code>sensor_4</code>가 <strong>전방</strong>, <code>sensor_5</code>가 <strong>후방</strong> 카메라이고, <code>sensor_0</code>–<code>sensor_3</code>은 <code>depth</code>와 <code>ir</code>만 발행합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_4/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 전방 카메라</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_5/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 후방 카메라</span></span></code></pre></div><h3 id="다른-호스트에서-실제-로봇에-붙을-때" tabindex="-1">다른 호스트에서 실제 로봇에 붙을 때 <a class="header-anchor" href="#다른-호스트에서-실제-로봇에-붙을-때" aria-label="Permalink to &quot;다른 호스트에서 실제 로봇에 붙을 때&quot;">​</a></h3><p>로봇에 닿는 인터페이스를 <strong>두 번째</strong> 인자로 넘기세요:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_4/rgb/compressed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp3s0</span></span></code></pre></div><p>로봇 쪽 비전 스택도 본인 PC에서 도달 가능한 인터페이스로 떠 있어야 합니다 — 로봇에서 <code>bash scripts/RBQ.bash -i &lt;nic&gt;</code> 로 실행하세요. 양쪽이 <strong>같은</strong> 인터페이스를 써야 하며, 다르면 <code>rate=0 Hz</code>가 됩니다.</p><blockquote><p><code>lo</code> 로 실행하면 CycloneDDS가 <code>selected interface &quot;lo&quot; is not multicast-capable: disabling multicast</code> 를 남깁니다. 정상이며 무해합니다 — 같은 호스트 안의 프로세스 사이에서는 디스커버리가 그대로 동작하고, 시뮬레이터가 정확히 그 경우입니다. 호스트를 넘어가는 구성에서만 실제 NIC가 필요합니다.</p></blockquote><h2 id="출력-예시" tabindex="-1">출력 예시 <a class="header-anchor" href="#출력-예시" aria-label="Permalink to &quot;출력 예시&quot;">​</a></h2><p>MuJoCo 시뮬레이터(<code>sim.bash --vision</code>)에서 <code>sensor_4</code>(전방 카메라)를 구독한 결과:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_image_echo] subscribed to &#39;rt/rbq/vision/sensor_4/rgb/compressed&#39; on interface &#39;lo&#39;</span></span>
<span class="line"><span>[rbq_image_echo] waiting for samples (Ctrl+C to exit)...</span></span>
<span class="line"><span>[rbq_image_echo] 1.0s  total=15  rate=15 Hz  last=13053 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 2.0s  total=29  rate=14 Hz  last=13080 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 3.0s  total=44  rate=15 Hz  last=13067 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] exiting, total samples = 44</span></span></code></pre></div><p>수신율이 일정하고 바이트 크기가 0이 아니며 <code>fmt=&#39;jpeg&#39;</code>이면 스트림이 정상입니다. <code>rate=0 Hz</code>이면 해당 토픽/인터페이스에서 발행 측을 찾지 못한 것이니 토픽 이름과 DDS 인터페이스를 확인하세요.</p>`,31)])])}const g=a(o,[["render",n]]);export{b as __pageData,g as default};
